def fill_credit_note_customer(apps, schema_editor):
    """الإشعارات الدائنة القديمة كلها على طلبات — العميل بييجي من الطلب."""
    PrintCreditNote = apps.get_model('printing', 'PrintCreditNote')
    for cn in PrintCreditNote.objects.filter(customer__isnull=True, order__isnull=False).select_related('order'):
        PrintCreditNote.objects.filter(pk=cn.pk).update(customer_id=cn.order.customer_id)


